from collections.abc import Callable

import pytest


def wrapped(job: Callable[[], str]) -> str:
    """Run `job` and return its result enclosed as 'start:<result>:end'."""
    return f"start:{job()}:end"


def test_wrapped_basic() -> None:
    assert wrapped(lambda: "hello") == "start:hello:end"


def test_wrapped_empty_result() -> None:
    assert wrapped(lambda: "") == "start::end"


def test_wrapped_propagates_exception() -> None:
    def failing_job() -> str:
        raise ValueError("boom")

    with pytest.raises(ValueError, match="boom"):
        wrapped(failing_job)


def test_wrapped_calls_job_exactly_once() -> None:
    call_count = 0

    def job() -> str:
        nonlocal call_count
        call_count += 1
        return f"count_{call_count}"

    res = wrapped(job)
    assert res == "start:count_1:end"
    assert call_count == 1

